interface.definition:
a!localVariables(
  local!orgteam: #"_a-0000eef8-4604-8000-9e54-011c48011c48_1134349"(
    orgId: ri!orgid,
    teamid: ri!teamid,
    isActive: true()
  ),


  local!getorgteamids:index(local!orgteam,#"urn:appian:record-field:v1:4eb1fdb2-adfe-4b4b-8a61-ccc9f1f5f947/4889b852-272c-42a8-81e1-414933737923",null()),
  local!getteamroles:#"_a-0000eef8-4604-8000-9e54-011c48011c48_1138645"(teamid: local!getorgteamids,isActive: true()),
  local!getTeamroleids:index(local!getteamroles,#"urn:appian:record-field:v1:139cb21e-dd78-4694-a8ad-b43e2d51226f/da39fffc-c223-49f0-b99c-5a3a8f8ad3b8",null()),
  local!getgroupdetails:#"_a-0000eef8-4604-8000-9e54-011c48011c48_1136584"(groupid: local!getTeamroleids,isactive: true()),
  local!getgroupname:index(local!getgroupdetails,#"urn:appian:record-field:v1:c4386edd-8146-4849-a78b-d8ad760265af/e8ca0cac-e7b4-4dfc-a87f-9c9f6e12a24c",null()),
  #"SYSTEM_SYSRULES_formLayout_v2"(
    contents: {
      #"SYSTEM_SYSRULES_cardLayout"(
        contents: {
          #"SYSTEM_SYSRULES_richTextDisplayField"(
            value: {
              #"SYSTEM_SYSRULES_richTextItem_v1"(
                text:" You will be added to the ",
                style: "STRONG",
                size: "STANDARD",
                color: "STANDARD"
              ),
              #"SYSTEM_SYSRULES_richTextItem_v1"(
                text: local!getgroupname,
                style: "STRONG",
                size: "STANDARD",
                color: "POSITIVE"
              ),
              #"SYSTEM_SYSRULES_richTextItem_v1"(
                text: " Groups",
                style: "STRONG",
                size: "STANDARD",
                color: "STANDARD"
              )
            }
          ),

        },
        padding: "NONE",
        showBorder: false(),
      )
    },
    buttons: #"SYSTEM_SYSRULES_ButtonLayout"(
      primaryButtons: {
        #"SYSTEM_SYSRULES_buttonWidget_v1"(
          label: "Submit",
          saveInto: {
            a!save(
              target:ri!submit,
              value:#"_a-0000eeda-0177-8000-9e52-011c48011c48_1085463"
            )
          },
          submit: true,
          loadingIndicator: true,
          style: "SOLID"
        )
      },
      secondaryButtons: {
        #"SYSTEM_SYSRULES_buttonWidget_v1"(
          label: "Cancel",
          value: true,
          saveInto: {
            a!save(
              target:ri!submit,
              value:#"_a-0000eeda-0177-8000-9e52-011c48011c48_1085469"
            )
          },
          validate: false,
          submit: true,
          style: "OUTLINE"
        )
      }
    ),
    titleBar: #"SYSTEM_SYSRULES_headerTemplateFull"(
      title: "Are You Sure  To Join The Team",
      secondaryText: "You will be added to the group",
      backgroundColor: "ACCENT"
    ),
    showTitleBarDivider: false,
    contentsWidth: "NARROW"
  )
)
